  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C11", "C30", "C105", "C113", "C88", "C78", "C195", "C203", "C212", "C208", "C177", "C194"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C11", "C30", "C105", "C113", "C88", "C78", "C195", "C203", "C212", "C208", "C177", "C194"],
  "claims": [
    {
      "claim": "L5 Caco-2 records show propranolol has high absorptive permeability with no meaningful efflux, e.g. A-B 40.9 and B-A 41.5 x10^-6 cm/s (C195), efflux ratio 0.83 (C203), and Papp 53.1 x10^-6 cm/s (C212); human jejunal perfusion gives P_eff 2.90 x10^-4 cm/s (C208).",
      "card_ids": ["C195", "C203", "C212", "C208"]
    },
    {
      "claim": "L5 metoprolol records also show high Caco-2 permeability (C177, C194), supporting adequate intestinal absorption for lipophilic basic amines similar to the query despite its low neutral fraction.",
      "card_ids": ["C177", "C194"]
    },
    {
      "claim": "No L5 record directly tests the query or cinacalcet gut-wall efflux or intestinal metabolism; absence of query-specific data is not evidence for F below 20%.",
      "card_ids": ["C195", "C203", "C212"]
    },
    {
      "claim": "L3 cinacalcet oral-exposure records show measurable AUC and Cmax after oral dosing (C113, C88, C78), and the ketoconazole interaction (C105) indicates CYP3A4-mediated first-pass but does not quantify absolute F.",
      "card_ids": ["C113", "C88", "C78", "C105"]
    },
    {
      "claim": "Direct fasted propranolol absolute F of 27.2% (C11, C30) remains above the 20% threshold and supports the high prediction for this basic amine scaffold.",
      "card_ids": ["C11", "C30"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C195", "C203", "C212", "C208", "C177", "C194"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability value is available for the query or cinacalcet.",
    "No query-specific gut-wall efflux or intestinal metabolism measurement is available; L5 records are for other molecules.",
    "First-pass metabolism is inferred from the cinacalcet-ketoconazole interaction but is not quantified for the query.",
    "The query's low neutral fraction may limit passive permeability, but no measured absorption data affirm low F.",
    "Most high-F L1/L2 records come from cirrhosis-modified conditions with reduced first-pass elimination, limiting transfer to healthy conditions."
  ],
  "decision_summary": "L5 adds mechanistic support for high passive intestinal permeability and minimal efflux for lipophilic basic amines similar to the query, strengthening the absorption component. Combined with measurable cinacalcet oral exposure and direct fasted propranolol F of 27.2%, the prediction remains high at F >= 20%; confidence stays moderate because no absolute F is available for the closest analog and first-pass remains unquantified."
}

